import { connectSegments, extendSegments, getSegmentOffsetFromSegment, segmentsFromPoints } from '../math/segments';
import { randomNormalWholeBetween, randomNumberBetween, randomWholeBetween } from '../math/random';
import {
    createRandomStaticParticleValues,
    createSimpleParticleSystem,
    forceGravity,
    forceWind,
    Particle,
} from './ParticleSystem';
import { rotateHue } from '../color/palettes';
import { TAU } from '../math/math';

export const getFiberStrokeOneSide = (path, thickness = 10, spacing = 1, fringeMax = 0) => {
    const stroke = [];
    for (let i = 0; i < thickness; i += spacing) {
        let string = [];
        path.forEach((segment) => {
            const offsetSegment = getSegmentOffsetFromSegment(segment, i);
            string.push(offsetSegment);
        });
        string = extendSegments(string, randomNormalWholeBetween(0, fringeMax));
        string = connectSegments(string);
        stroke.push(string);
    }
    return stroke;
};

export const getFiberStrokeMid = (path, thickness = 10, spacing = 1, fringeMax = 0) => {
    let direction = 1;
    const sideThickness = Math.round(thickness / 2);
    const stroke = [];
    for (let i = 0; i < sideThickness; i += spacing) {
        let string = [];
        path.forEach((segment) => {
            const offsetSegment = getSegmentOffsetFromSegment(segment, i, direction);
            string.push(offsetSegment);
        });
        string = extendSegments(string, randomNormalWholeBetween(0, fringeMax));
        string = connectSegments(string);
        stroke.push(string);
    }

    direction *= -1;

    for (let i = spacing; i < sideThickness; i += spacing) {
        let string = [];
        path.forEach((segment) => {
            const offsetSegment = getSegmentOffsetFromSegment(segment, i, direction);
            string.push(offsetSegment);
        });
        string = extendSegments(string, randomNormalWholeBetween(0, fringeMax));
        string = connectSegments(string);
        stroke.push(string);
    }
    return stroke;
};

export const createRakeStroke = (
    particleSystem,
    initialParticleProps,
    strokeBounds,
    endingBounds,
    length = 250,
    strokeThickness = 20,
    segmentSpacing = 2,
    endFringes = 10
) => {
    const p = new Particle(initialParticleProps);
    const path = particleSystem.createParticlePath(p, length, endingBounds);

    const pathSegments = segmentsFromPoints(path);

    return getFiberStrokeMid(pathSegments, strokeThickness, segmentSpacing, endFringes);
};

