export const drawRakeStroke = (rcanvas, segments, strokeWeightFn, strokeColorFn, onStrokeColorFn, twist = 0) => {
    rcanvas.push();

    segments.forEach((s, i) => {
        if (strokeWeightFn) {
            rcanvas.strokeWeight(strokeWeightFn(i));
        }

        if (strokeColorFn) {
            rcanvas.stroke(strokeColorFn(i));
        }

        rcanvas.strokeRound();

        s.forEach((seg, i) => {
            // skip segments?
            // if (i % 10) rcanvas.point(seg.start.x + xnoise, seg.start.y + ynoise);
            // if (!chance(10)) rcanvas.lineSeg(seg);

            // noise "wave" to the lines?
            const xfreq = 20;
            const yfreq = 1;
            const xamp = 20;
            const yamp = 1;

            const x1 = seg.start.x;
            const y1 = seg.start.y;
            const x2 = seg.end.x;
            const y2 = seg.end.y;

            const xnoise = 0; // Math.cos(x1 / xfreq) * xamp;
            const ynoise = 0; // Math.sin(y1 / yfreq) * yamp;
            const xnoise2 = 0; // Math.cos(x2 / xfreq) * xamp;
            const ynoise2 = 0; // Math.sin(y2 / yfreq) * yamp;

            if (onStrokeColorFn) {
                rcanvas.stroke(onStrokeColorFn(s.length, i));
            }

            rcanvas.line(x1 + xnoise, y1 + ynoise, x2 + xnoise2, y2 + ynoise2);
        });
    });

    rcanvas.pop();
};

export const particlesForFilledRakeRect = (rcanvas, bounds) => {
    // these look good
    // amp 3.86, fre .0009
    // amplitude 5.0497540727797645 frequency 0.0014
    // amplitude 4.522012295286075 frequency 0.0011
    // amplitude 0.7235477056751152 frequency 0.0019
    // amplitude 2.222186740418964 frequency 0.001
    // amplitude 2.6253780793977977 frequency 0.001
    // amplitude 8.62063203062658 frequency 0.09
    // amplitude 11.134030038569783 frequency 2.594558184021308
    // amplitude 9.941455272658716 frequency 1.3019805386354086
    // amplitude 3.0996506666994583 frequency 3.7317148569266814

    const amplitude = TAU; // randomNumberBetween(0, 20);
    const frequency = randomNumberBetween(5, 11) * 0.00001; // 0.00008; //
    const velocity = 2; // randomWholeBetween(1, 10);

    const particles = createSimpleParticleSystem(rcanvas, bounds, frequency, amplitude, velocity);
    particles.addForce(forceGravity(5));
    particles.addForce(forceWind(1));

    // console.log('particlesForFilledRakeRect: velocity', velocity, 'amplitude', amplitude, 'frequency', frequency);

    return particles;
};

// Inspiration but i'm not even close https://www.reddit.com/r/generative/comments/oukiq5/painting/
export const drawFilledRakeRect = (rcanvas, bounds, particles, color, colorVariance = 1, density = 1) => {
    let strokeLength = bounds.h;
    let maxStrokeBristleThickness = 4;
    let minStrokeThickness = 5;
    let maxStrokeThickness = 20;
    let minSegmentSpacing = 1;
    let maxSegmentSpacing = 5;
    let maxEndFringe = 5;
    let steps = 2;

    if (density === 2) {
        maxStrokeBristleThickness = 2;
        minStrokeThickness = 18;
        maxStrokeThickness = 25;
        minSegmentSpacing = 1;
        maxSegmentSpacing = 3;
        maxEndFringe = 10;
        steps = 4;
    }

    if (density === 3) {
        maxStrokeBristleThickness = 1;
        minStrokeThickness = 20;
        maxStrokeThickness = 30;
        minSegmentSpacing = 1;
        maxSegmentSpacing = 5;
        maxEndFringe = 20;
        steps = 7;
    }

    const startX = bounds.x - minStrokeThickness / 2;
    const endX = bounds.x2 - minStrokeThickness;
    const startY = bounds.y - minStrokeThickness / 2;
    const endY = bounds.y2 - minStrokeThickness / 2;

    rcanvas.push();

    rcanvas.stroke(color);

    const varyStroke = (strokeIdx) => randomWholeBetween(0.25, maxStrokeBristleThickness);
    const varyStrokeColor = (strokeIdx) =>
        rotateHue(
            color,
            randomNumberBetween(colorVariance * -1, colorVariance),
            randomNumberBetween(colorVariance * -1, colorVariance),
            randomNumberBetween(colorVariance * -1, colorVariance)
        );

    for (let x = startX; x < endX; x += steps) {
        const strokeThickness = randomNumberBetween(minStrokeThickness, maxStrokeThickness);
        const segmentSpacing = randomNumberBetween(minSegmentSpacing, maxSegmentSpacing);
        const endFringes = randomNumberBetween(1, maxEndFringe);

        const startingProps = createRandomStaticParticleValues(bounds.x, bounds.x2, bounds.y, bounds.y2);
        startingProps.x = x;
        startingProps.y = bounds.y;
        const offsetSegments = createRakeStroke(
            particles,
            startingProps,
            bounds,
            bounds,
            strokeLength,
            strokeThickness,
            segmentSpacing,
            endFringes
        );
        drawRakeStroke(rcanvas, offsetSegments, varyStroke, varyStrokeColor); //
    }

    strokeLength = bounds.w;

    for (let y = startY; y < endY; y += steps) {
        const strokeThickness = randomNumberBetween(minStrokeThickness, maxStrokeThickness);
        const segmentSpacing = randomNumberBetween(minSegmentSpacing, maxSegmentSpacing);
        const endFringes = randomNumberBetween(1, maxEndFringe);

        const startingProps = createRandomStaticParticleValues(bounds.x, bounds.x2, bounds.y, bounds.y2);
        startingProps.x = bounds.x;
        startingProps.y = y;
        const offsetSegments = createRakeStroke(
            particles,
            startingProps,
            bounds,
            bounds,
            strokeLength,
            strokeThickness,
            segmentSpacing,
            endFringes
        );
        drawRakeStroke(rcanvas, offsetSegments, varyStroke, varyStrokeColor); //
    }

    rcanvas.pop();
};
