import tinycolor from 'tinycolor2';

import { CanvasGridLayout, largePrintScreen, ratio, scaleValueToRatio } from '../v2/RCanvas';
import { bicPenBlue, Palette, rotateHue, warmWhite } from '../color/palettes';

import { createSimpleParticleSystem, createRandomStaticParticleValues } from '../v2/ParticleSystem';
import { chance, randomNumberBetween, randomWholeBetween } from '../math/random';
import { createRakeStroke, drawRakeStroke, drawFilledRakeRect, particlesForFilledRakeRect } from '../v2/rakeStroke';

export const rakeStrokes = (sketch) => {
    const sketchSize = 1500;

    const config = {
        name: 'rakeStrokes',
        edition: 2,
        width: sketchSize,
        height: scaleValueToRatio(ratio.golden)(sketchSize),
    };

    const backgroundColor = warmWhite.clone().lighten(10);
    const foreColor = bicPenBlue.clone();

    const { rcanvas, datGUI } = sketch;
    let layout;
    let particles;

    let counter = 0;

    const settings = {
        palette: new Palette(),
        maxItterations: randomWholeBetween(10, 200),
        amplitude: randomNumberBetween(0.1, 5),
        frequency: randomNumberBetween(0.00001, 1),
        velocity: 7,
        margins: sketchSize * 0.1,
        layoutColumns: randomWholeBetween(1, 4),
        layoutRows: 1,
        minBrushSize: 5,
        maxBrushSize: sketchSize * 0.15,
        maxStokeWeight: randomWholeBetween(2, 5),
        maxColorVariance: randomWholeBetween(2, 20),
        escapeBoundsChance: randomWholeBetween(100, 200),
    };

    const onSettingsChange = (setting) => (newValue) => {
        console.log(setting, newValue);
        console.log(JSON.stringify(settings));
        reset();
    };

    const setupSetting = (key, min = 0, max = 100, step = 1) => {
        if (!datGUI) return;
        const c = datGUI.add(settings, key, min, max, step);
        c.onFinishChange(onSettingsChange(key));
    };

    const setupDatGUI = () => {
        setupSetting('maxItterations', 1, 1000, 1);
        setupSetting('layoutColumns', 1, 4, 1);
        setupSetting('layoutRows', 1, 4, 1);
        setupSetting('amplitude', 0.1, 5, 0.1);
        setupSetting('frequency', 0.00001, 2, 0.00001);
        setupSetting('velocity', 1, 20, 1);
        setupSetting('minBrushSize', 1, 10, 1);
        setupSetting('maxBrushSize', 2, 200, 1);
        setupSetting('maxStokeWeight', 2, 20, 1);
        setupSetting('maxColorVariance', 1, 50, 1);
        setupSetting('escapeBoundsChance', 1, 200, 10);
    };

    const setup = () => {
        setupDatGUI();

        // rcanvas.showLayout(layout);
        rcanvas.stroke(foreColor);
        // rcanvas.fill(foreColor);
        rcanvas.noFill();

        // rcanvas.blendMode('multiply');
        // rcanvas.blendMode('hard-light');
        // rcanvas.blendMode('soft-light');

        layout = new CanvasGridLayout(
            rcanvas.width,
            rcanvas.height,
            settings.margins,
            settings.layoutColumns,
            settings.layoutRows,
            settings.margins
        );
        particles = createSimpleParticleSystem(
            rcanvas,
            layout.bounds,
            settings.frequency,
            settings.amplitude,
            settings.velocity
        );
        // particles.addForce(forceGravity(3));
        // particles.addForce(forceWind(3));

        // rcanvas.showNoise(layout.bounds, );

        // console.log(settings);

        rcanvas.background(backgroundColor);
    };

    const reset = () => {
        counter = 0;

        layout = new CanvasGridLayout(
            rcanvas.width,
            rcanvas.height,
            settings.margins,
            settings.layoutColumns,
            settings.layoutRows,
            settings.margins
        );
        particles = createSimpleParticleSystem(
            rcanvas,
            layout.bounds,
            settings.frequency,
            settings.amplitude,
            settings.velocity
        );

        rcanvas.background(backgroundColor);
        sketch.restart();
    };

    const draw = () => {
        layout.cells.forEach((bounds) => {
            const endBounds = chance(settings.escapeBoundsChance) ? null : bounds;
            // const endBounds = bounds;
            const strokeLength = randomWholeBetween(bounds.w / 4, bounds.w);
            const minStrokeThickness = randomWholeBetween(settings.minBrushSize, settings.maxBrushSize);
            const segmentSpacing = randomNumberBetween(1, 3);
            const endFringes = randomWholeBetween(0, 50);

            const startingProps = createRandomStaticParticleValues(bounds.x, bounds.x2, bounds.y, bounds.y2);
            const offsetSegments = createRakeStroke(
                particles,
                startingProps,
                bounds,
                endBounds,
                strokeLength,
                minStrokeThickness,
                segmentSpacing,
                endFringes
            );

            const colorVariance = randomWholeBetween(1, settings.maxColorVariance);

            const strokeColor = settings.palette.oneOf();

            rcanvas.stroke(strokeColor);

            const varyStroke = (strokeIdx) => randomWholeBetween(1, settings.maxStokeWeight);

            const varyStrokeColor = (strokeIdx) =>
                rotateHue(
                    strokeColor,
                    randomNumberBetween(colorVariance * -1, colorVariance),
                    randomNumberBetween(colorVariance * -1, colorVariance),
                    randomNumberBetween(colorVariance * -1, colorVariance)
                );

            // const varyOnSegment = (segLen, segIdx) => tinycolor.mix(strokeColor, 'red', (segIdx / segLen) * 100);

            drawRakeStroke(rcanvas, offsetSegments, varyStroke, varyStrokeColor);
        });

        return counter++ < settings.maxItterations;
    };

    return {
        settings,
        config,
        reset,
        setup,
        draw,
    };
};
